// Reads the RBA cash rate page and pulls the current cash rate target
// from the newest row of the table: | date | change | cash rate |
// Saves a row on every run, even when the rate hasn't changed: that's how the site's
// audit can tell this feed is alive. The score only counts rows where the rate changed.
try {
  const html = String($input.first().json.data || '');
  const row = html.match(/<tbody[\s\S]*?<tr>\s*<th[^>]*>([^<]+)<\/th>\s*<td[^>]*>[^<]*<\/td>\s*<td[^>]*>\s*([\d.]+)\s*<\/td>/);
  if (!row) throw new Error('could not find the cash rate table');

  const value = parseFloat(row[2]);
  // Safety check: never save a number that can't be a cash rate
  if (!(value >= 0.1 && value <= 20)) throw new Error('unexpected value ' + row[2]);

  // Adelaide's date: a 7am run is still yesterday in UTC
  const date = new Intl.DateTimeFormat('en-CA', { timeZone: 'Australia/Adelaide' }).format(new Date());
  return [{ json: { value, date } }];
} catch (e) {
  console.log('Cash rate skipped: ' + e.message);
  return []; // nothing saved, the other feeds keep running
}

// The RBA publishes each month's credit figures at the END of the following month,
// so last month's page usually doesn't exist yet. Ask for last month AND the month
// before; the next step uses whichever page is actually published.
const now = new Date();
const items = [];
for (const monthsBack of [1, 2]) {
  const d = new Date(now.getFullYear(), now.getMonth() - monthsBack, 1);
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yy = String(d.getFullYear()).slice(-2);
  items.push({ json: { url: `https://www.rba.gov.au/statistics/frequency/fin-agg/${d.getFullYear()}/fin-agg-${mm}${yy}.html` } });
}
return items;

// Reads the RBA Financial Aggregates page and pulls monthly HOUSING credit growth
// (the newest month in the "Housing" row). Pages that aren't published yet are skipped.
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
  'August', 'September', 'October', 'November', 'December'];

for (const item of $input.all()) {
  // RBA writes negative numbers with a special minus sign; turn it into a normal "-"
  const html = String(item.json.data || '').replace(/&minus;|&#8722;|−/g, '-');

  const title = html.match(/<title>\s*Financial Aggregates\s+([A-Za-z]+)\s+(\d{4})/);
  const row = html.match(/Housing\s*<\/th>\s*<td[^>]*>\s*(-?[\d.]+)\s*<\/td>\s*<td[^>]*>\s*(-?[\d.]+)\s*<\/td>/);
  if (!title || !row) continue; // e.g. a "page not found" for a month not published yet

  const month = MONTHS.indexOf(title[1]);
  const value = parseFloat(row[2]);
  if (month < 0 || !(value > -5 && value < 5)) continue;

  return [{ json: { value, date: `${title[2]}-${String(month + 1).padStart(2, '0')}-01` } }];
}

console.log('Housing credit skipped: no published RBA page found');
return [];

// ---- Helpers for the ABS Data API (same in each ABS step) ----
// Turns an ABS response into a list of { period, value }, oldest first.
function readAbs(raw) {
  if (!raw || raw.error) throw new Error('ABS request failed');
  let root = typeof raw.data === 'string' ? JSON.parse(raw.data) : raw;
  if (root.data && root.data.dataSets) root = root.data; // current ABS format wraps everything in "data"
  const dims = (root.structure || root.structures[0]).dimensions.observation;
  const timePos = dims.findIndex(d => d.id === 'TIME_PERIOD');
  const rows = [];
  for (const [key, obs] of Object.entries(root.dataSets[0].observations)) {
    const value = Number(obs[0]);
    if (obs[0] === null || Number.isNaN(value)) continue;
    rows.push({ period: dims[timePos].values[Number(key.split(':')[timePos])].id, value });
  }
  if (!rows.length) throw new Error('ABS returned no figures');
  return rows.sort((a, b) => a.period.localeCompare(b.period));
}
// "2026-09" -> "2026-09-01"   "2026-Q2" -> "2026-06-01"
function periodToDate(p) {
  const q = p.match(/^(\d{4})-Q([1-4])$/);
  return q ? `${q[1]}-${String(q[2] * 3).padStart(2, '0')}-01` : `${p.slice(0, 7)}-01`;
}

// Seasonally adjusted unemployment rate (the headline figure ABS reports)
try {
  const rows = readAbs($input.first().json);
  const latest = rows[rows.length - 1];
  const value = Math.round(latest.value * 10) / 10;
  if (!(value > 1 && value < 20)) throw new Error('unexpected value ' + latest.value);
  return [{ json: { value, date: periodToDate(latest.period) } }];
} catch (e) {
  console.log('Unemployment skipped: ' + e.message);
  return [];
}

