// Population growth over the last 12 months (number of people).
// ABS gives the population in thousands each quarter, so compare the latest
// quarter with the same quarter a year earlier.
try {
  const rows = readAbs($input.first().json);
  const latest = rows[rows.length - 1];
  const [year, quarter] = latest.period.split('-');
  const yearAgo = rows.find(r => r.period === `${Number(year) - 1}-${quarter}`);
  if (!yearAgo) throw new Error('no figure for a year earlier');

  const value = Math.round((latest.value - yearAgo.value) * 1000);
  if (!(value > 50000 && value < 1500000)) throw new Error('unexpected value ' + value);
  return [{ json: { value, date: periodToDate(latest.period) } }];
} catch (e) {
  console.log('Population growth skipped: ' + e.message);
  return [];
}

// National weekend auction clearance rate from the weekly PropertyUpdate report.
// The page can contain more than one week's report, each saying
// "average clearance rate of X% ... than the Y% reported over the previous week".
// The newest is the one that no other report refers to as the previous week.
try {
  const html = String($input.first().json.data || '');
  const text = html.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');

  const reports = [...text.matchAll(/average clearance rate of (?:just |only )?([\d.]+)%[^%]{0,150}?the ([\d.]+)% reported over the previous week/gi)]
    .map(m => ({ current: parseFloat(m[1]), previous: parseFloat(m[2]) }));
  let pick = reports.find(r => !reports.some(o => o !== r && o.previous === r.current));

  // Fallback if the wording changes: last "average clearance rate of X%" on the page
  if (!pick) {
    const any = [...text.matchAll(/average clearance rate of (?:just |only )?([\d.]+)%/gi)];
    if (any.length) pick = { current: parseFloat(any[any.length - 1][1]) };
  }
  if (!pick || !(pick.current > 10 && pick.current < 100)) throw new Error('no clearance rate found');

  const published = html.match(/"datePublished":"(\d{4}-\d{2}-\d{2})/);
  const date = published ? published[1] : new Date().toISOString().split('T')[0];
  return [{ json: { value: pick.current, date } }];
} catch (e) {
  console.log('Clearance rate skipped: ' + e.message);
  return [];
}

// SQM national rental vacancy rate: the page holds the full monthly history
// in a "var data = [...]" block; take the newest month
try {
  const html = String($input.first().json.data || '');
  const match = html.match(/var data = (\[.*?\]);/s);
  if (!match) throw new Error('could not find the data block');

  const data = JSON.parse(match[1])
    .sort((a, b) => (a.year - b.year) || (a.month - b.month));
  const latest = data[data.length - 1];
  const value = Math.round(Number(latest.vr) * 10000) / 100; // 0.0139 -> 1.39 (%)
  if (!(value > 0.1 && value < 10)) throw new Error('unexpected value ' + latest.vr);

  return [{ json: { value, date: `${latest.year}-${String(latest.month).padStart(2, '0')}-01` } }];
} catch (e) {
  console.log('Vacancy rate skipped: ' + e.message);
  return [];
}
